import {createBotManagementActionReader} from './bot-management-view.mjs';

// Capability decisions need facts about a receipt, not its session transcript,
// file contents, audio/image bytes, tool arguments, or returned business rows.
// These facts are generated by the server from the original JSON in SQLite.
const object=(source,fields)=>`json_object(${fields.flatMap(key=>[`'${key}'`,`json(${source} -> '$.${key}')`]).join(',')})`;
const request=['enabled','workspace','employeeId','deviceId','configurationRevision'];
const phone=['loaded','injected','fixture','executionSource','workspace','employeeId','targetDeviceId','actionId','runtime','profile','runtimeProfile','serverName'];
const worker=['platform','employeeId','workspace','revision','controlEpoch','status','processAlive','lastHeartbeat','sourceActionId'];
const native=['schemaVersion','resource','operation','employeeId','revision','nativeVersion','status','code','executionSource'];
const workerObject=object('w',worker).slice(0,-1)+",'_workspacePresent',json_type(w,'$.workspace') IS NOT NULL)";
const truthyValue=(source,path)=>`CASE WHEN json_type(${source},'$.${path}') IS NULL OR json_type(${source},'$.${path}') IN ('null','false') THEN 0 WHEN json_type(${source},'$.${path}')='text' THEN length(json_extract(${source},'$.${path}'))>0 WHEN json_type(${source},'$.${path}') IN ('integer','real') THEN json_extract(${source},'$.${path}')<>0 ELSE 1 END`;
const truthy=path=>truthyValue('d',path);
const whitespace='char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)';
const parse=value=>{try{return JSON.parse(value);}catch{return null;}};
const exited=exit=>exit?.launched===true&&Number.isSafeInteger(exit.rootPid)&&exit.rootPid>0&&exit.rootConfirmed===true&&exit.rootExitCode===0&&!exit.cancelled&&!exit.failureCode&&((exit.treeConfirmed===true&&exit.activeProcesses===0)||['darwin','linux'].includes(exit.platform)&&exit.supervisor==='direct');
export function createBotWorkbenchActionReader(repo){
  const read=createBotManagementActionReader(repo);
  const select=repo.db.prepare(`WITH source AS (
    SELECT CASE WHEN json_valid(payload_json) THEN payload_json ELSE '{}' END p,
      CASE WHEN json_valid(result_json) THEN result_json ELSE '{}' END r FROM a2a_actions WHERE id=? AND workspace_id=?
  ), receipt AS (
    SELECT p,r,CASE WHEN ${truthyValue('r','result')} THEN r -> '$.result' ELSE r END v,
      CASE WHEN ${truthyValue('r','nativeOperation')} THEN r -> '$.nativeOperation' ELSE COALESCE(r -> '$.result.nativeOperation','{}') END n FROM source
  ), detail AS (
    SELECT p,r,v,n,COALESCE(n -> '$.data','{}') d,
      CASE WHEN json_type(v,'$.terminalMcp.toolCalls')='array' THEN v -> '$.terminalMcp.toolCalls' ELSE COALESCE(v -> '$.terminalMcp.tool_calls','[]') END calls FROM receipt
  ) SELECT ${object('p -> \'$.terminalMcp\'',request)} phone_request,
    (${truthyValue('r','nativeOperation')} OR ${truthyValue('r','result.nativeOperation')}) native_present,
    ${object('n',native)} native_header,v -> '$.processExit' process_exit,
    d -> '$.connected' connected,d -> '$.success' success,d -> '$.stopConfirmed' stop_confirmed,
    ${object('v -> \'$.terminalMcp\'',phone)} phone_receipt,
    (SELECT json_group_array(${object('c',['toolName','ok','deviceId'])} -> '$') FROM (SELECT CASE WHEN type='object' THEN value ELSE '{}' END c FROM json_each(calls))) phone_calls,
    (SELECT json_group_array(json_object('deviceId',json(c -> '$.ids.deviceId'))) FROM (SELECT CASE WHEN type='object' THEN value ELSE '{}' END c FROM json_each(calls))) phone_ids,
    CASE WHEN json_type(d)='array' THEN json_array_length(d) WHEN json_type(d,'$.items')='array' THEN json_array_length(d,'$.items') ELSE 0 END item_count,
    json_type(d,'$.tools')='array' tools_array,CASE WHEN json_type(d,'$.tools')='array' THEN json_array_length(d,'$.tools') ELSE 0 END tool_count,
    ${truthy('room')} room_present,${truthy('task')} task_present,${truthy('state')} state_present,
    (${truthy('staged')} OR ${truthy('pending_id')} OR ${truthy('mutation.staged')} OR ${truthy('mutation.pending_id')}) staged,
    substr(json_extract(d,'$.code'),1,160) data_code,substr(json_extract(d,'$.reason'),1,160) data_reason,substr(json_extract(d,'$.error'),1,160) data_error,
    substr(json_extract(n,'$.executionSource'),1,160) native_execution_source,
    (json_type(r,'$.fixture')='true' OR json_type(v,'$.fixture')='true' OR json_extract(r,'$.executionSource')='fixture' OR json_extract(v,'$.executionSource')='fixture' OR json_extract(n,'$.executionSource')='fixture' OR json_extract(n,'$.data.executionSource')='fixture') fixture,
    substr(json_extract(d,'$.task.status'),1,160) task_status,
    CASE WHEN json_type(d,'$.state.status')='text' AND length(json_extract(d,'$.state.status'))>0 THEN substr(json_extract(d,'$.state.status'),1,160) WHEN json_type(d,'$.state.state')='text' THEN substr(json_extract(d,'$.state.state'),1,160) END state_status,
    d -> '$.run' run,
    (SELECT json_group_array(${workerObject}) FROM (SELECT CASE WHEN type='object' THEN value ELSE '{}' END w FROM json_each(CASE WHEN json_type(d,'$.runtime')='array' THEN d -> '$.runtime' ELSE '[]' END))) gateway_workers,
    CASE WHEN json_type(v,'$.residentExit') IS NULL OR json_type(v,'$.residentExit') IN ('null','false') THEN 0 ELSE 1 END resident_exit,
    length(trim(CASE WHEN json_type(d,'$.transcript')='text' AND length(json_extract(d,'$.transcript'))>0 THEN json_extract(d,'$.transcript') ELSE COALESCE(json_extract(d,'$.text'),'') END,${whitespace}))>0 transcript_present,
    EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(d,'$.files')='array' THEN d -> '$.files' ELSE '[]' END) WHERE type='object' AND substr(json_extract(value,'$.mimeType'),1,6)='audio/' AND json_type(value,'$.audioBase64')='text' AND length(json_extract(value,'$.audioBase64'))>0) audio_present,
    EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(p,'$.attachments')='array' THEN p -> '$.attachments' ELSE '[]' END) WHERE type='object' AND substr(COALESCE(json_extract(value,'$.mimeType'),json_extract(value,'$.mime_type')),1,6)='image/') image_input,
    CASE WHEN json_type(r,'$.collaboration.actions')='array' THEN json_array_length(r,'$.collaboration.actions') ELSE 0 END collaboration_count
    FROM detail`);
  return(actionId,workspaceId)=>{
    const action=read(actionId,workspaceId);if(!action)return null;
    const row=select.get(actionId,workspaceId),phoneRequest=parse(row.phone_request),phoneReceipt=parse(row.phone_receipt);
    if(row.native_present)action.result.nativeOperation={...parse(row.native_header),...(action.result.nativeOperation?.data?{data:action.result.nativeOperation.data}:{})};
    else delete action.result.nativeOperation;
    if(phoneRequest?.enabled!==null)action.payload.terminalMcp=phoneRequest;
    if(phoneReceipt?.workspace!==null){
      const calls=parse(row.phone_calls)||[],ids=parse(row.phone_ids)||[];
      action.result.terminalMcp={...phoneReceipt,toolCalls:calls.map((call,index)=>({...call,ids:ids[index]}))};
    }
    const workers=(parse(row.gateway_workers)||[]).map(value=>{const {_workspacePresent,...worker}=value;if(!_workspacePresent)delete worker.workspace;return worker;});
    action.capabilityFacts={schemaVersion:1,fixture:Boolean(row.fixture),exited:Boolean(exited(parse(row.process_exit))),connected:parse(row.connected),success:parse(row.success),stopConfirmed:parse(row.stop_confirmed),itemCount:row.item_count,toolsArray:Boolean(row.tools_array),toolCount:row.tool_count,roomPresent:Boolean(row.room_present),taskPresent:Boolean(row.task_present),taskStatus:row.task_status,statePresent:Boolean(row.state_present),stateStatus:row.state_status,run:parse(row.run),staged:Boolean(row.staged),dataCode:row.data_code,dataReason:row.data_reason,dataError:row.data_error,gatewayWorkers:workers,residentExit:Boolean(row.resident_exit),transcriptPresent:Boolean(row.transcript_present),audioPresent:Boolean(row.audio_present),imageInput:Boolean(row.image_input),collaborationCount:row.collaboration_count};
    return action;
  };
}
